  - issue has either “good first issue” or “help wanted”
  - issue has no assignee
  - issue has no open PR
  - comment matches a strong claim pattern
- Otherwise, defer to a maintainer and add a visible “pending claim” marker.
- Re-run the claim-check script manually from the workflow, because GitHub’s built-in assignment does not trigger the same issue-event path.

Use this workflow file:

```yaml
name: Auto-claim on issue comment

on:
  issue_comment:
    types: [created]

permissions:
  issues: write
  contents: read

jobs:
  auto_claim:
    if: github.event.issue.pull_request == null
    runs-on: ubuntu-latest

    steps:
      - name: Check if comment is a claim
        id: claim
        uses: actions/github-script@v7
        with:
          script: |
            const body = (context.payload.comment.body || '').trim();
            const author = context.payload.comment.user.login;
            const isBot = context.payload.comment.user.type === 'Bot';

            if (isBot) {
              core.setOutput('is_claim', 'false');
              core.setOutput('reason', 'bot-comment');
              return;
            }

            const pattern = /(i(?:'|’)?d like to (?:take|work on this)|can i take this|may i take this|i can take this|\/claim)/i;
            const isClaim = pattern.test(body);

            core.setOutput('is_claim', isClaim ? 'true' : 'false');
            core.setOutput('author', author);
            core.setOutput('issue_number', String(context.payload.issue.number));

      - name: Exit if not a claim
        if: steps.claim.outputs.is_claim != 'true'
        run: echo "No claim detected."

      - name: Skip if issue already assigned or already has an open PR
        id: state
        uses: actions/github-script@v7
        with:
          script: |
            const issue = context.payload.issue;
            if ((issue.assignees || []).length > 0) {
              core.setOutput('decision', 'already_assigned');
              return;
            }

            const issueNumber = issue.number;
            const repo = context.repo.repo;
            const owner = context.repo.owner;

            const pulls = await github.rest.pulls.list({
              owner,
              repo,
              state: 'open'
            });

            const hasOpenPR = pulls.data.some(pr =>
              (pr.body || '').includes(`#${issueNumber}`) ||
              (pr.title || '').includes(`#${issueNumber}`)
            );

            if (hasOpenPR) {
              core.setOutput('decision', 'has_open_pr');
              return;
            }

            core.setOutput('decision', 'ok_to_assign');

      - name: Require safe labels before auto-assigning
        id: safe
        if: steps.state.outputs.decision == 'ok_to_assign'
        uses: actions/github-script@v7
        with:
          script: |
            const labels = (context.payload.issue.labels || []).map(l => (l.name || '').toLowerCase());
            const safe = ['good first issue', 'help wanted'];

            const hasSafeLabel = labels.some(label => safe.includes(label));

            if (!hasSafeLabel) {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.payload.issue.number,
                labels: ['pending-claim']
              }).catch(() => {});

              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.payload.issue.number,
                body: `@${context.payload.comment.user.login} Thanks — I detected a claim, but this issue is not in a low-risk auto-assign category. A maintainer will review it within 24h.`
              });

              core.setOutput('assign', 'false');
              return;
            }

            core.setOutput('assign', 'true');

      - name: Assign the commenter
        if: steps.safe.outputs.assign == 'true'
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.issues.addAssignees({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.payload.issue.number,
              assignees: [context.payload.comment.user.login]
            });

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.payload.issue.number,
              body: `Thanks @${context.payload.comment.user.login} — I assigned you to this issue. A maintainer may still ask for clarification before work begins.`
            });

      - name: Re-run the repo claim check
        if: steps.safe.outputs.assign == 'true'
        run: |
          python3 -V
          if [ -f "requirements.txt" ]; then
            python3 -m pip install -r requirements.txt
          fi
          python3 quality/check_issue_claim.py --issue ${{ github.event.issue.number }}
```

