jobs:
  claim-notice:
    if: github.event.issue.pull_request == null
    runs-on: ubuntu-latest

    steps:
      - name: Detect claim
        id: detect
        uses: actions/github-script@v7
        with:
          script: |
            const body = (context.payload.comment.body || '').trim();
            const pattern = /(i(?:'|’)?d like to (?:take|work on this)|can i take this|may i take this|i can take this|\/claim)/i;
            const isClaim = pattern.test(body);
            core.setOutput('is_claim', isClaim ? 'true' : 'false');

      - name: Post maintainer review notice
        if: steps.detect.outputs.is_claim == 'true'
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.payload.issue.number,
              body: `@${context.payload.comment.user.login} Thanks for the claim. A maintainer will review this issue and confirm assignment within 24h.`
